const GAME_STYLE_IDS = ["normal", "chaos", "grand"];
const LOCAL_GAME_STYLE_IDS = [...GAME_STYLE_IDS, "campaign"];
const MULTIPLAYER_TIME_CONTROL_PRESETS = Object.freeze({
  blitz: { label: "블리츠", minutes: 3, incrementSeconds: 3, draftSeconds: 20, grandDraftSeconds: 10 },
  rapid: { label: "래피드", minutes: 10, incrementSeconds: 5, draftSeconds: 40, grandDraftSeconds: 20 },
  classic: { label: "클래식", minutes: 30, incrementSeconds: 15, draftSeconds: 60, grandDraftSeconds: 30 }
});
const MULTIPLAYER_DEFAULT_TIME_CONTROL = "rapid";
const MULTIPLAYER_ANY_PREFERENCE = "any";
const MULTIPLAYER_GAME_STYLE_PREFERENCES = Object.freeze([...GAME_STYLE_IDS, MULTIPLAYER_ANY_PREFERENCE]);
const MULTIPLAYER_TIME_CONTROL_PREFERENCES = Object.freeze([
  ...Object.keys(MULTIPLAYER_TIME_CONTROL_PRESETS),
  MULTIPLAYER_ANY_PREFERENCE
]);
const MULTIPLAYER_PREFERENCES_STORAGE_KEY = "augment-chess:multiplayer-preferences:v1";
const MULTIPLAYER_MATCHMAKING_TICKET_STORAGE_KEY = "augment-chess:quick-match-ticket:v1";
const MULTIPLAYER_MATCHMAKING_POLL_MS = 800;
const MULTIPLAYER_MATCHMAKING_TICKET_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/iu;
function loadMultiplayerPreferences() {
  try {
    const value = JSON.parse(localStorage.getItem(MULTIPLAYER_PREFERENCES_STORAGE_KEY) || "null");
    return {
      gameStyle: MULTIPLAYER_GAME_STYLE_PREFERENCES.includes(value?.gameStyle) ? value.gameStyle : "normal",
      timeControl: MULTIPLAYER_TIME_CONTROL_PREFERENCES.includes(value?.timeControl) ? value.timeControl : MULTIPLAYER_DEFAULT_TIME_CONTROL
    };
  } catch {
    return { gameStyle: "normal", timeControl: MULTIPLAYER_DEFAULT_TIME_CONTROL };
  }
}
function persistMultiplayerPreferences() {
  try {
    localStorage.setItem(MULTIPLAYER_PREFERENCES_STORAGE_KEY, JSON.stringify({
      gameStyle: multiplayerPreferenceGameStyle,
      timeControl: multiplayerPreferenceTimeControl
    }));
  } catch {
  }
}
function loadMultiplayerMatchmakingTicketId() {
  try {
    const value = sessionStorage.getItem(MULTIPLAYER_MATCHMAKING_TICKET_STORAGE_KEY) || "";
    return MULTIPLAYER_MATCHMAKING_TICKET_PATTERN.test(value) ? value.toLowerCase() : null;
  } catch {
    return null;
  }
}
function persistMultiplayerMatchmakingTicketId(ticketId) {
  try {
    if (MULTIPLAYER_MATCHMAKING_TICKET_PATTERN.test(String(ticketId ?? ""))) {
      sessionStorage.setItem(MULTIPLAYER_MATCHMAKING_TICKET_STORAGE_KEY, String(ticketId).toLowerCase());
    } else {
      sessionStorage.removeItem(MULTIPLAYER_MATCHMAKING_TICKET_STORAGE_KEY);
    }
  } catch {
  }
}
