  if (retiredCampaignRoute) {
    setMultiplayerRouteBooting(false);
    window.history.replaceState({}, "", "/");
    toast("이전 캠페인 링크는 종료되었습니다. 친선전에서 새 캠페인 방을 만들어 주세요.");
    return false;
  }
