async function writeFriendlyRoomCodeToClipboard() {
  const roomCode = String(betaFriendlyRoomActive ? betaFriendlyRoomView.roomCode || "" : online.roomCode || "");
  if (!(betaFriendlyRoomActive || online.enabled) || !roomCode) throw new Error("room code unavailable");
  await writeTextToClipboard(roomCode);
  return roomCode;
}
async function writeTextToClipboard(text) {
  const value = String(text || "");
  if (!value) throw new Error("clipboard value unavailable");
  if (navigator.clipboard?.writeText && window.isSecureContext) {
    await navigator.clipboard.writeText(value);
    return value;
  }
  const textarea = document.createElement("textarea");
  textarea.value = value;
  textarea.setAttribute("readonly", "");
  textarea.style.position = "fixed";
  textarea.style.opacity = "0";
  document.body.append(textarea);
  textarea.select();
  try {
    if (!document.execCommand("copy")) throw new Error("copy command failed");
  } finally {
    textarea.remove();
  }
  return value;
}
async function copyFriendlyRoomCode(button = null) {
  try {
    const roomCode = await writeFriendlyRoomCodeToClipboard();
    button?.classList.add("copied");
    toast(`방 코드 ${roomCode} 복사됨`);
    window.setTimeout(() => button?.classList.remove("copied"), 1200);
  } catch (error) {
    console.warn("Failed to copy friendly room code", error);
    toast("방 코드를 복사하지 못했습니다.");
  }
}
