  let moved = false;
  let startX = 0;
  let startY = 0;
  const closeDuringScroll = () => {
    suppressLibraryCardHelpClicks(library);
    clearFloatingCardHelp(library);
  };
  library.addEventListener("pointerdown", (event) => {
    if (!isMobileCardPreviewMode() || event.pointerType === "mouse") return;
    tracking = true;
    moved = false;
    startX = event.clientX;
    startY = event.clientY;
  }, true);
  library.addEventListener("pointermove", (event) => {
    if (!tracking || !isMobileCardPreviewMode()) return;
    const distance = Math.max(Math.abs(event.clientX - startX), Math.abs(event.clientY - startY));
    if (distance <= 5) return;
    moved = true;
    closeDuringScroll();
  }, true);
  const end = () => {
    if (moved) closeDuringScroll();
    tracking = false;
    moved = false;
  };
  library.addEventListener("pointerup", end, true);
  library.addEventListener("pointercancel", end, true);
  library.addEventListener("scroll", () => {
    if (!isMobileCardPreviewMode()) return;
    closeDuringScroll();
  }, { passive: true, capture: true });
