function bindCardGridDragScroll(grid) {
  if (!grid || grid.dataset.dragScrollBound) return;
  grid.dataset.dragScrollBound = "true";
  let startY = 0;
  let startScrollTop = 0;
  let dragging = false;
  let moved = false;
  let suppressHelpClickTimer = null;
  const suppressHelpClick = () => {
    window.clearTimeout(suppressHelpClickTimer);
    grid.dataset.suppressCardHelpClick = "true";
    suppressLibraryCardHelpClicks(grid.closest(".dev-library"));
    suppressHelpClickTimer = window.setTimeout(() => {
      delete grid.dataset.suppressCardHelpClick;
    }, 180);
  };
  const clearGridHelp = () => {
    clearFloatingCardHelp(grid.closest(".compare-library") || grid);
  };
  grid.addEventListener("pointerdown", (event) => {
    if (event.button !== 0 || grid.scrollHeight <= grid.clientHeight) return;
    dragging = true;
    moved = false;
    startY = event.clientY;
    startScrollTop = grid.scrollTop;
    grid.classList.add("drag-scrolling");
    grid.setPointerCapture?.(event.pointerId);
  });
  grid.addEventListener("pointermove", (event) => {
    if (!dragging) return;
    const deltaY = startY - event.clientY;
    if (Math.abs(deltaY) > 4) {
      moved = true;
      suppressHelpClick();
      clearGridHelp();
    }
    grid.scrollTop = startScrollTop + startY - event.clientY;
    event.preventDefault();
  });
  const stop = (event) => {
    if (!dragging) return;
    if (moved) {
      suppressHelpClick();
      clearGridHelp();
    }
    dragging = false;
    moved = false;
    grid.classList.remove("drag-scrolling");
    grid.releasePointerCapture?.(event.pointerId);
  };
  grid.addEventListener("pointerup", stop);
  grid.addEventListener("pointercancel", stop);
  grid.addEventListener("pointerleave", stop);
  grid.addEventListener("scroll", () => {
    if (!isMobileCardPreviewMode()) return;
    suppressHelpClick();
    clearGridHelp();
  }, { passive: true });
}
