  ["left", "right", "top", "bottom", "width"].forEach((prop) => panel.style.removeProperty(prop));
  if (!placement) return;
  if (window.matchMedia("(orientation: portrait) and (max-width: 900px), (max-width: 720px)").matches) return;
  const pending = currentAuction()?.pendingPlacementCell;
  const pendingX = Number(pending?.clientX);
