els.newGameButton.addEventListener("click", async () => {
  if (returnToSimpleBoardEditorFromGame()) return;
  if (betaFriendlyRoomActive) {
    const betaRoom = globalThis.augmentChessBetaFriendlyRoom;
    if (betaFriendlyGameInProgress()) {
      await betaRoom?.resign?.();
      return;
    }
    if (betaFriendlyWaitingToStart()) {
      if (!betaFriendlyIsHost()) {
        toast("새 게임은 방장만 시작할 수 있습니다.");
        return;
      }
      if (betaFriendlySetupCommitInProgress()) {
        toast("방 설정을 저장한 뒤 게임을 시작합니다.");
        return;
      }
      betaRoom?.startGame?.();
      return;
    }
    if (betaFriendlyGameFinished()) {
      await betaRoom?.returnToRoom?.();
      return;
    }
    return;
  }
  if (await returnDetachedMultiplayerInlineReviewToHome()) return;
  if (await returnDetachedOnlineReviewToLobby()) return;
  if (await returnCampaignToLobbyAfterReview()) return;
  if (await returnFriendlyRoomGuestToLobbyAfterReview()) return;
  if (online.enabled) {
    if (onlineGameStarted() && ONLINE_ACTIVE_GAME_MODES.has(state.mode)) {
      if (online.role !== "player" || !online.playerColor) {
        toast("관전자는 기권할 수 없습니다.");
        return;
      }
      if (!await confirmForfeit(online.playerColor)) return;
      if (!await prepareOnlineForfeit(online.playerColor)) {
        renderAll();
        return;
      }
      endGame(opponent(online.playerColor), `${COLOR_LABELS[online.playerColor]} 기권`);
      renderAll();
      return;
    }
    if (friendlyRoomCanReturnToLobby()) {
      await returnFriendlyRoomToLobbyAfterReview();
      return;
    }
    if (isCampaignLobbyState()) {
      const campaign = restartableCampaign();
      if (campaign) {
        if (!online.isHost) {
          toast("방을 만든 사람만 캠페인을 시작할 수 있습니다.");
          return;
        }
        if (!onlineSeatsReady()) {
          toast("백과 흑 플레이어가 모두 입장해야 시작할 수 있습니다.");
          return;
        }
        if (startWaitingOnlineCampaign()) return;
        void startCampaign(campaign.id);
        return;
      }
      useNormalModeForEmptyCampaignSelection({ onlineMode: true });
    }
    if (!online.isHost) {
      toast("새 게임은 방장만 시작할 수 있습니다.");
      return;
    }
    if (!onlineSeatsReady()) {
      toast("백과 흑 플레이어가 모두 입장해야 시작할 수 있습니다.");
      return;
    }
    if (startWaitingOnlineCampaign()) return;
    clearOnlineLocalReplay();
    const editorStartConfig = simpleBoardEditorFriendlyStartForCurrentRoom();
    if (editorStartConfig || legacyEditorFriendlyRoomTransport) {
      if (!editorStartConfig || !restartSimpleBoardEditorOnlineGame(editorStartConfig)) {
        toast("보드 편집기의 최초 배치를 불러오지 못했습니다.");
        return;
      }
    } else {
      resetGame();
    }
    state.onlineGameStarted = true;
    online.eventNonce = 0;
    disableOnlineBlockedModes();
    queueOnlineStateSave();
    renderAll();
    return;
  }
  if (isCampaignContext() && ["idle", "gameover"].includes(state.mode)) {
    const campaign = restartableCampaign();
    if (!campaign) {
      useNormalModeForEmptyCampaignSelection();
      resetGame();
      return;
    }
    void startCampaign(campaign.id);
    return;
  }
  if (["play", "draft", "auction", "auction-placement"].includes(state.mode)) {
    const resigningColor = isAiSingleMode() ? humanControlledColor() : state.turn;
    if (!await confirmForfeit()) return;
    endGame(opponent(resigningColor), `${COLOR_LABELS[resigningColor]} 기권`);
    renderAll();
    return;
  }
  if (state.mode === "gameover") {
    resetGame(false);
    state.cardArchiveAvailable = true;
    renderAll();
    return;
  }
  resetGame();
});
