function setSettingsOpen(open) {
  if (!els.settingsPanel || !els.settingsBackdrop) return;
  const wasOpen = !els.settingsPanel.hidden;
  if (open) setDesignOpen(false);
  if (open && !wasOpen) betaFriendlySetupCommitReleased = false;
  els.settingsPanel.hidden = !open;
  els.settingsBackdrop.hidden = !open;
  updateSettingsClockPanelVisibility(open);
  if (wasOpen && !open && betaFriendlyRoomActive) commitBetaFriendlySetupQueue();
}
function updateSettingsClockPanelVisibility(open = !els.settingsPanel?.hidden) {
  if (!els.settingsClockPanel) return;
  const hasVisibleClockControl = Boolean(
    els.clockLimitControl && !els.clockLimitControl.hidden || els.fischerIncrementControl && !els.fischerIncrementControl.hidden || els.draftClockControl && !els.draftClockControl.hidden
  );
  els.settingsClockPanel.hidden = !open || !hasVisibleClockControl;
}
