els.deckButton?.addEventListener("click", () => {
  if (shouldHideCampaignDeckForTurn()) return;
  if (state.mode === "draft") {
    state.draftBoardPreview = false;
    renderAll();
    return;
  }
  if (isOnlineSpectator() || isAcgViewer()) {
    state.cardArchiveOpen = true;
    state.devLibraryOpen = false;
    state.opponentLibraryOpen = false;
    state.auctionInventoryOpen = false;
    state.bloodMoonEffectLibraryOpen = false;
    renderAll();
    return;
  }
  if (state.mode === "idle" && state.cardArchiveAvailable) {
    state.cardArchiveOpen = true;
    state.devLibraryOpen = false;
    state.opponentLibraryOpen = false;
    state.auctionInventoryOpen = false;
    state.bloodMoonEffectLibraryOpen = false;
    renderAll();
    return;
  }
  if (isAuctionCampaignActive() && ["auction", "auction-placement"].includes(state.mode) && currentAuction()) {
    state.auctionInventoryOpen = true;
    state.devLibraryOpen = false;
    state.cardArchiveOpen = false;
    state.opponentLibraryOpen = false;
    state.bloodMoonEffectLibraryOpen = false;
    renderAll();
    return;
  }
  if (state.devMode) {
    state.devLibraryOpen = true;
    state.cardArchiveOpen = false;
    state.opponentLibraryOpen = false;
    state.auctionInventoryOpen = false;
    state.bloodMoonEffectLibraryOpen = false;
  } else {
    state.opponentLibraryOpen = true;
    state.devLibraryOpen = false;
    state.cardArchiveOpen = false;
    state.auctionInventoryOpen = false;
    state.bloodMoonEffectLibraryOpen = false;
  }
  handleTutorialDeckPileOpened();
  renderAll();
});
